<script setup lang="ts">
import type { Customer } from '~/types/billing'
import { billingDate } from '~/utils/billing'
definePageMeta({ layout: 'admin', middleware: 'superadmin' })
const { rows, pagination, pending, error, refresh, search, status, page, message, failure, saving, mutate } = await useManagement<Customer>('customers')
const selected = ref<Customer | null>(null)
const form = reactive({ name: '', status: 'active' })
const searchInput = ref('')
function edit(customer: Customer) { selected.value = customer; Object.assign(form, { name: customer.name, status: customer.status }); failure.value = '' }
async function save() { if (selected.value && await mutate(`management/customers/${selected.value.id}`, form, 'PATCH')) selected.value = null }
</script>
<template><div><p class="eyebrow">Account administration</p><h1 class="page-title mt-2">Customers</h1><p class="mt-2 text-text-secondary">Find customers, review their usage, and control account access.</p><p v-if="message" class="mt-5 rounded-lg bg-success-bg p-3 text-success" role="status">{{ message }}</p><form class="my-6 flex flex-wrap gap-3" @submit.prevent="search=searchInput;page=1"><input v-model="searchInput" class="input max-w-sm" aria-label="Search customers" placeholder="Search name or email"><select v-model="status" class="input w-auto" aria-label="Account status" @change="page=1"><option value="">All statuses</option><option value="active">Active</option><option value="suspended">Suspended</option></select><button class="btn-secondary">Search</button></form><div class="surface overflow-hidden"><LoadingState v-if="pending"/><div v-else-if="error" class="p-8" role="alert">Unable to load customers. <button class="text-brand" @click="refresh()">Retry</button></div><div v-else class="overflow-x-auto"><table class="admin-table"><thead><tr><th>Customer</th><th>Status</th><th>Role</th><th>Links</th><th>Joined</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody><tr v-for="customer in rows" :key="customer.id"><td><p class="font-medium">{{ customer.name }}</p><p class="text-xs text-text-muted">{{ customer.email }}</p></td><td><span :class="customer.status==='active'?'badge-success':'badge-danger'">{{ customer.status }}</span></td><td>{{ customer.role }}</td><td>{{ customer.links_count }}</td><td>{{ billingDate(customer.created_at) }}</td><td><div class="flex gap-2"><button class="text-brand" :disabled="customer.role!=='user'" @click="edit(customer)">Edit</button><NuxtLink :to="`/admin/subscriptions?customer=${customer.id}`" class="text-brand">Subscriptions →</NuxtLink></div></td></tr><tr v-if="!rows.length"><td colspan="6" class="py-12 text-center">No customers match your search.</td></tr></tbody></table></div><AdminPagination v-if="pagination" :current="pagination.current_page" :last="pagination.last_page" :total="pagination.total" :pending="pending" @change="page=$event"/></div><AdminDialog v-if="selected" :title="`Edit ${selected.name}`" @close="selected=null"><form class="grid gap-5" @submit.prevent="save"><label class="label">Name<input v-model="form.name" class="input mt-2" maxlength="120" required></label><label class="label">Account status<select v-model="form.status" class="input mt-2"><option value="active">Active</option><option value="suspended">Suspended</option></select></label><p class="text-xs text-text-muted">Suspending an account revokes its sign-in tokens. Its links and subscription records are retained.</p><p v-if="failure" role="alert" class="text-danger">{{ failure }}</p><div class="flex justify-between"><button type="button" class="btn-secondary" :disabled="saving" @click="mutate(`management/customers/${selected.id}/password-reset`)">Send password reset</button><button class="btn-primary" :disabled="saving">{{ saving?'Saving…':'Save changes' }}</button></div></form></AdminDialog></div></template>
